create or replace function integration_control.penta_identity_source_custody_invoke_v1() returns jsonb language plpgsql security definer set search_path='pg_catalog','integration_control','vault','extensions','chlom_runtime' as $$ declare v_role text:=coalesce((nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'),''); v_control text; v_response extensions.http_response; v_safe_body jsonb; begin if session_user not in ('postgres','supabase_admin') and v_role<>'service_role' then raise exception 'service_role_required'; end if; select decrypted_secret into v_control from vault.decrypted_secrets where name='stripe_production_control_gateway_secret_v1' order by created_at desc limit 1; if v_control is null then raise exception 'control_secret_missing'; end if; v_response:=chlom_runtime.dail_http_v1(('POST'::extensions.http_method,'https://tzajnzshmtzjenqulehq.supabase.co/functions/v1/penta-identity-source-custody-v1'::varchar,array[row('x-ct-control-secret',v_control)::extensions.http_header,row('content-type','application/json')::extensions.http_header],'application/json'::varchar,'{}'::varchar)::extensions.http_request); if coalesce(v_response.content,'') ~ '^\s*[\{\[]' then v_safe_body:=v_response.content::jsonb; else v_safe_body:=jsonb_build_object('non_json_gateway_body',true,'body_sha256',encode(extensions.digest(coalesce(v_response.content,''),'sha256'),'hex'),'body_bytes',octet_length(coalesce(v_response.content,''))); end if; return jsonb_build_object('http_status',v_response.status,'response',v_safe_body,'secret_exposed',false); end $$; revoke all on function integration_control.penta_identity_source_custody_invoke_v1() from anon,authenticated;